Section CANSEC1. Context {rc : runConstT}.
Definition rlowW (spv : Z) (iv : Z * Z) : Prop :=
  (0 <= fst iv /\ snd iv <= ATOP /\ (snd iv <= 0x10000 \/ 0x5d000 <= fst iv \/ (RCTX <= fst iv /\ snd iv <= RCTX + 928)))
  \/ iv = (spv - 144, spv).

